// src/App.js
import React from "react";
import { BrowserRouter as Router, Routes, Route, Link } from 'react';
import ListDetail from "./routes/listDetail";

function App() {
  return (
    <Router>
      <div style={{ padding: "20px", fontFamily: "Arial, sans-serif" }}>
        <h1>🛒 Shopping Lists</h1>
        <p>Select a list to view details:</p>
        <ul>
          <li>
            <Link to="/list/1">Family Shopping List</Link>
          </li>
          <li>
            <Link to="/list/2">Party Preparation</Link>
          </li>
        </ul>

        <Routes>
          <Route path="/list/:id" element={<listDetail />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
